// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CartoonEyesProps = Record<string, any>;

const CartoonEyes: React.FC<CartoonEyesProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 8,
  scleraColor = "#ffffff",
  pupilColor = "#0f172a",
  questionMarkColor = "#ffffff",
  questionMarkCount = 25,
}) => {
  useFontLoader(["Fredoka"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const s = Math.min(width, height);

  // Eye Dimensions
  const scleraSize = s * 0.18;
  const pupilSize = s * 0.06;
  const maxEyeMove = (scleraSize - pupilSize) / 2 - s * 0.01; // Keep pupil slightly inside

  // Eye Animation Sequence (Timings based on 30fps)
  // 0-20: to Left
  // 20-40: hold Left
  // 40-60: to Right
  // 60-80: hold Right
  // 80-100: to Center
  // 100-120: to Up
  // 120-140: hold Up
  // 140-160: to Down
  // 160-180: hold Down
  // 180-200: to Center & Squint

  const pupilX = interpolate(
    frame,
    [0, 20, 40, 60, 80, 100, 120, 140, 160, 180, 200, durationInFrames],
    [0, -maxEyeMove, -maxEyeMove, maxEyeMove, maxEyeMove, 0, 0, 0, 0, 0, 0, 0],
    { easing: Easing.inOut(Easing.quad), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const pupilY = interpolate(
    frame,
    [0, 20, 40, 60, 80, 100, 120, 140, 160, 180, 200, durationInFrames],
    [0, 0, 0, 0, 0, 0, -maxEyeMove, -maxEyeMove, maxEyeMove, maxEyeMove, 0, 0],
    { easing: Easing.inOut(Easing.quad), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Squinting (helpless expression) at the end
  const squintRy = interpolate(
    frame,
    [180, 200],
    [50, 28],
    { easing: Easing.inOut(Easing.ease), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const pupilScale = interpolate(
    frame,
    [180, 200],
    [1, 0.85],
    { easing: Easing.inOut(Easing.ease), extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Pre-calculate deterministic question marks
  const qMarks = useMemo(() => {
    return new Array(questionMarkCount).fill(0).map((_, i) => {
      // Start appearing around frame 90 (when looking up/down), spread over next 90 frames
      const delay = 90 + (i * (90 / questionMarkCount));
      // Golden angle distribution for natural spread
      const angle = (i * 137.5) * (Math.PI / 180); 
      
      const distanceMin = scleraSize * 1.5;
      const distanceMax = s * 0.45;
      const baseDistance = distanceMin + random(`dist-${i}`) * (distanceMax - distanceMin);
      
      const sizeOffset = random(`size-${i}`) * 0.5 + 0.5; // 0.5 to 1.0
      const fontSize = s * 0.05 * sizeOffset + s * 0.03;
      
      const rotationStart = random(`rotStart-${i}`) * 90 - 45;
      const rotationEnd = rotationStart + (random(`rotDir-${i}`) > 0.5 ? 60 : -60);
      
      const floatSpeed = random(`float-${i}`) * 0.5 + 0.2;

      return { delay, angle, baseDistance, fontSize, rotationStart, rotationEnd, floatSpeed };
    });
  }, [questionMarkCount, scleraSize, s]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      
      {/* Eyes Container */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: s * 0.45,
          height: scleraSize,
          display: "flex",
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "center",
          transition: "none",
        }}
      >
        {/* Left Eye */}
        <div
          style={{
            width: scleraSize,
            height: scleraSize,
            backgroundColor: scleraColor,
            clipPath: `ellipse(50% ${squintRy}% at 50% 50%)`,
            position: "relative",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transition: "none",
            boxShadow: "inset 0px 0px 20px rgba(0,0,0,0.1)", // Subtle inner shadow
          }}
        >
          {/* Pupil */}
          <div
            style={{
              width: pupilSize,
              height: pupilSize,
              backgroundColor: pupilColor,
              borderRadius: "50%",
              position: "absolute",
              transform: `translate(${pupilX}px, ${pupilY}px) scale(${pupilScale})`,
              transition: "none",
            }}
          />
        </div>

        {/* Right Eye */}
        <div
          style={{
            width: scleraSize,
            height: scleraSize,
            backgroundColor: scleraColor,
            clipPath: `ellipse(50% ${squintRy}% at 50% 50%)`,
            position: "relative",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transition: "none",
            boxShadow: "inset 0px 0px 20px rgba(0,0,0,0.1)",
          }}
        >
          {/* Pupil */}
          <div
            style={{
              width: pupilSize,
              height: pupilSize,
              backgroundColor: pupilColor,
              borderRadius: "50%",
              position: "absolute",
              transform: `translate(${pupilX}px, ${pupilY}px) scale(${pupilScale})`,
              transition: "none",
            }}
          />
        </div>
      </div>

      {/* Floating Question Marks */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: 0,
          height: 0,
          transition: "none",
        }}
      >
        {qMarks.map((qm, i) => {
          const timeSinceAppeared = frame - qm.delay;
          
          if (timeSinceAppeared < 0) return null;

          const scale = spring({
            fps,
            frame: timeSinceAppeared,
            config: { damping: 12, mass: 0.8, stiffness: 150 },
          });

          // Drift slowly outward and float upwards slightly
          const driftOutward = interpolate(
            timeSinceAppeared,
            [0, 200],
            [scleraSize * 0.8, qm.baseDistance],
            { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
          );

          const x = Math.cos(qm.angle) * driftOutward;
          const y = Math.sin(qm.angle) * driftOutward - (timeSinceAppeared * qm.floatSpeed);

          const rotation = interpolate(
            timeSinceAppeared,
            [0, 200],
            [qm.rotationStart, qm.rotationEnd],
            { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
          );

          // Subtle fade in to avoid harsh pops before spring takes over, 
          // and fade out at the very end of the video
          const opacity = interpolate(
            frame,
            [durationInFrames - 15, durationInFrames],
            [1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={`qm-${i}`}
              style={{
                position: "absolute",
                color: questionMarkColor,
                fontFamily: "Fredoka",
                fontWeight: 700,
                fontSize: qm.fontSize,
                transform: `translate(-50%, -50%) translate(${x}px, ${y}px) scale(${scale}) rotate(${rotation}deg)`,
                opacity,
                transition: "none",
                textShadow: "0px 4px 12px rgba(0,0,0,0.15)",
                lineHeight: 1,
              }}
            >
              ?
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default CartoonEyes;